# ReAct(JSON 도구 호출) 대 CodeAct — LLM 은 대본대로 움직이는 가짜(stub), 토큰 수는 가정값
RATES = {"USA": (1.0, .08), "Japan": (.0068, .10), "Germany": (1.1, .19), "India": (.012, .18)}
PRICE = {"USA": 899, "Japan": 120000, "Germany": 700, "India": 75000}
SHIP  = {"USA": 10, "Japan": 6.4, "Germany": 20, "India": 15}
T = {"lookup_rates": RATES.get, "lookup_phone_price": PRICE.get, "estimate_shipping_cost": SHIP.get,
     "convert_and_tax": lambda p, r, t: round(p * r * (1 + t), 2),
     "estimate_final_price": lambda p, s: round(p + s, 2)}
P, OUT, OBS, CODE_TOK = 400, 30, 10, 120   # 프롬프트, 턴당 출력, 관찰, 코드 덩어리 토큰
CODE = """final = {}
for c in ['USA', 'Japan', 'Germany', 'India']:
    r, t = lookup_rates(c)
    u = convert_and_tax(lookup_phone_price(c), r, t)
    final[c] = estimate_final_price(u, estimate_shipping_cost(c))
best = min(final, key=final.get)"""

def react():                          # 도구 호출 하나 = LLM 한 턴, 매 턴 전체 문맥을 다시 읽는다
    ctx, read, turns = P, 0, 0
    for _ in range(4 * 5):           # 나라 4 x 도구 5 (실제 값 계산은 CodeAct 쪽과 같다)
        read += ctx; ctx += OUT + OBS; turns += 1
    return turns + 1, read + ctx      # + 최종 답 턴

def codeact():
    env = dict(T); exec(CODE, env)    # 반복·min 은 파이썬 인터프리터가 한다
    read = P + (P + CODE_TOK + OBS)   # 1턴: 코드 작성, 2턴: 결과 보고 답
    return 2, read, env["best"], env["final"][env["best"]]

print("ReAct  : 턴 %d, 누적 입력 토큰 %d" % react())
print("CodeAct: 턴 %d, 누적 입력 토큰 %d -> %s $%.2f" % codeact())

# 원본 그대로 / 관찰 마스킹 / 요약(compaction) — 턴별 문맥 토큰 비교(토큰 수는 가정값)
SYS, R, A, O = 2000, 300, 200, 2600    # 시스템, 턴당 추론·행동·관찰 토큰 (관찰 ≈ 84%)
KEEP, LIMIT, SUMMARY = 3, 40000, 1500  # 마스킹: 최근 3턴 관찰만 원문, 압축 한도, 요약 크기

def raw(t):  return SYS + t * (R + A + O)
def mask(t): return SYS + t * (R + A) + min(t, KEEP) * O + max(0, t - KEEP) * 20  # 20 = "[생략]" 표지
def compact(t, ctx=SYS):
    for _ in range(t):
        ctx += R + A + O
        if ctx > LIMIT: ctx = SYS + SUMMARY        # 한도를 넘으면 앞부분을 요약 하나로
    return ctx

total = {"raw": 0, "mask": 0, "compact": 0}
for t in range(1, 31):
    for k, f in (("raw", raw), ("mask", mask), ("compact", compact)):
        total[k] += f(t)                             # 매 턴 문맥 전체를 다시 읽는다(캐시 무시)
    if t in (5, 10, 20, 30):
        print(f"턴 {t:2d}: 원본 {raw(t):6d}  마스킹 {mask(t):6d}  압축 {compact(t):6d}")
print("30턴 누적 입력:", total, f"마스킹 절감 {1 - total['mask'] / total['raw']:.0%}")
